	owner,
	agentId,
	children,
	showBack,
	backLabel,
	backTo,
	title,
	className,
}: {
	owner: string;
	agentId: string;
	children: ReactNode;
	showBack?: boolean;
	backLabel: string;
	backTo: string;
	/** When set, a centered sticky header (title + gutter back arrow) owns the
	 *  page header — the detail form should NOT render its own title. */
	title?: ReactNode;
	/** Override shell width (default max-w-3xl). */
	className?: string;
}) {
	const navigate = useNavigate();

	const goBack = () => {
		void navigate({
			to: backTo,
			params: { owner, agentId },
		});
	};

	return (
		<div className={cn("mx-auto w-full max-w-3xl pb-8", className)}>
			{title ? (
				<>
					<AgentSubpageHeader
						title={title}
						onBack={goBack}
						backLabel={backLabel}
					/>
					{children}
				</>
			) : showBack ? (
				<WithBackGutter onBack={goBack} backLabel={backLabel}>
					{children}
				</WithBackGutter>
			) : (
				children
			)}
		</div>
	);
}

