import { Link, Outlet, useLocation, useNavigate } from "@tanstack/react-router";
import {
	Cpu,
	Lock,
	Settings as SettingsIcon,
	Shield,
	Sparkles,
} from "lucide-react";
import { type ComponentType, useEffect } from "react";
import {
	AgentEditorForm,
	type AgentSection,
} from "@/components/agents/agent-editor-form";
import { ProposalReviewShell } from "@/components/agents/proposal-review-shell";
import { useCurrentOrg } from "@/hooks/use-current-org";
import { useMembers } from "@/hooks/use-members";
import { useOrgContext } from "@/hooks/use-org-context";
import {
	type AgentItem,
	useAgents,
	useResolvedPath,
	useSystemAgentId,
} from "@/lib/api";
import { useAuthState } from "@/lib/auth-state";
import { cn } from "@/lib/utils";

/** The definition surfaces behind the sidebar's single Configure row. Chat and
 *  Behaviors stay out: they have runtime state and their own sidebar rows. */
export type AgentConfigTab =
	| "skills"
	| "guardrails"
	| "permissions"
	| "models"
	| "settings";

const CONFIG_TAB_META: {
	tab: AgentConfigTab;
	label: string;
	icon: ComponentType<{ className?: string }>;
}[] = [
	{ tab: "skills", label: "Skills", icon: Sparkles },
	{ tab: "guardrails", label: "Guardrails", icon: Shield },
	{ tab: "permissions", label: "Permissions", icon: Lock },
	{ tab: "models", label: "Models", icon: Cpu },
	{ tab: "settings", label: "Settings", icon: SettingsIcon },
];

/** The config tab a pathname falls under, or null on a non-config page
 *  (chat, behaviors, conversations). Legacy /identity URLs still resolve and
 *  render the identity fields, which live on the Settings tab. */
export function activeConfigTab(
	base: string,
	pathname: string,
): AgentConfigTab | null {
	for (const { tab } of CONFIG_TAB_META) {
		if (
			pathname === `${base}/${tab}` ||
			pathname.startsWith(`${base}/${tab}/`)
		) {
			return tab;
		}
	}
	if (pathname === `${base}/identity` || pathname === `${base}/identity/`) {
		return "settings";
	}
	return null;
}

function ConfigTabLink({
	owner,
	agentId,
	tab,
	label,
	icon: Icon,
	activeTab,
}: {
	owner: string;
	agentId: string;
	tab: AgentConfigTab;
	label: string;
	icon: ComponentType<{ className?: string }>;
	activeTab: AgentConfigTab;
}) {
	const active = activeTab === tab;
	return (
		<Link
			to={`/$owner/agents/$agentId/${tab}`}
			params={{ owner, agentId }}
			className={cn(
				"inline-flex shrink-0 items-center gap-1.5 rounded-md px-2 py-1 text-sm transition-colors",
				active
					? "font-semibold text-foreground"
					: "text-muted-foreground hover:bg-muted/60 hover:text-foreground",
			)}
		>
			<Icon className="h-4 w-4 shrink-0" />
			{label}
		</Link>
	);
}

function AgentConfigTabs({
	owner,
	agentId,
	activeTab,
}: {
	owner: string;
	agentId: string;
	activeTab: AgentConfigTab;
}) {
	// The Permissions tab reads/writes the org-scoped write-gate envelope; its
	// endpoints require org settings admin. Hide it from regular members so they
	// never land on a 403 error state (they'd have no way to load or save it).
	const { orgContext } = useOrgContext();
	const { isAdmin } = useMembers(orgContext.organizationId);
	const tabs = isAdmin
		? CONFIG_TAB_META
		: CONFIG_TAB_META.filter(({ tab }) => tab !== "permissions");
	return (
		<div className="flex min-w-0 max-w-full flex-wrap items-center justify-center gap-x-2 gap-y-1">
			{tabs.map(({ tab, label, icon }) => (
				<ConfigTabLink
					key={tab}
					owner={owner}
					agentId={agentId}
					tab={tab}
					label={label}
					icon={icon}
					activeTab={activeTab}
				/>
			))}
		</div>
	);
}

