238			isReady && canManageWorkspace ? organizationId : null,
239		);
240		const { data: publicConnectorDefinitions = [] } =
241			usePublicConnectorDefinitions(canReadPublicWorkspace ? ownerSlug : null);
242		const effectiveConnectorDefinitions = canManageWorkspace
243			? connectorDefinitions
244			: publicConnectorDefinitions;
245	
246		const memoryConnectorGroups = useOptionalMemoryConnectorGroups();
247		const connectionFilterIds = filters.connectionIds;
248		const hasConnectionFilter = (connectionFilterIds?.length ?? 0) > 0;
249		const { data: filteredConnections = [] } = useConnections(
250			isReady && canManageWorkspace ? (organizationId ?? "") : "",
251			{
252				connectionIds: connectionFilterIds ?? undefined,
253				enabled:
254					!memoryConnectorGroups &&
255					isReady &&
256					canManageWorkspace &&
257					hasConnectionFilter,
258			},
259		);
260		const feedFilterIds = filters.feedIds;
261		const hasFeedFilter = (feedFilterIds?.length ?? 0) > 0;
262		const { data: workspaceFeeds = [] } = useAllFeeds(
263			isReady && canManageWorkspace ? organizationId : null,
264			{
265				feedIds: feedFilterIds ?? undefined,
266				enabled: isReady && canManageWorkspace && hasFeedFilter,
267			},
268		);
269	
270		const connectionLabelSources = useMemo(() => {
271			if (memoryConnectorGroups) {
272				return memoryConnectorGroups.groups.flatMap((group) =>
273					group.connections.map((connection) => ({
274						id: connection.id,
275						display_name: connection.display_name,
276						connector_name: group.connector_name,
277						connector_key: group.connector_key,
278					})),
