372			if (hasConnectionFilter && connectionFilterIds?.length === 1) {
373				const connection = connectionLabelSources.find(
374					(c) => c.id === connectionFilterIds[0],
375				);
376				if (connection?.connector_key) {
377					links.connectionIds = connectionSourceLink(ownerSlug, {
