381				}
382			}
383	
384			if (
385				agentFilterId &&
386				watcherFilterId == null &&
387				!scheduleScopeId &&
388				(filters.platforms?.length ?? 0) === 0
389			) {
390				links.agentId = agentFeedsSourceLink(ownerSlug, agentFilterId);
391			}
392	
393			if (agentFilterId && watcherFilterId != null) {
394				links.watcherId = watcherSourceLink(
395					ownerSlug,
396					agentFilterId,
397					String(watcherFilterId),
398				);
399			}
400	
401			if (agentFilterId && scheduleScopeId) {
402				links.schedule = scheduleSourceLink(
403					ownerSlug,
