406				);
407			}
408	
409			if (listenFilterLabel && agentFilterId) {
410				links.listen = agentFeedsSourceLink(ownerSlug, agentFilterId);
411			}
412	
413			return links;
414		}, [
415			agentFilterId,
416			connectionFilterIds,
417			connectionLabelSources,
418			feedFilterIds,
419			hasConnectionFilter,
420			hasFeedFilter,
421			filters.platforms,
422			listenFilterLabel,
423			ownerSlug,
424			scheduleScopeId,
425			watcherFilterId,
426			workspaceFeeds,
427		]);
428	
429		// Classifiers only available when entity is specified
