440			: publicClassifiersData;
441		const classifierGroups = useMemo<BehaviorClassifierGroup[]>(() => {
442			const groupMap = new Map<string, BehaviorClassifierGroup>();
443			for (const c of effectiveClassifiersData || []) {
444				const key = c.behavior_name ?? "__global__";
445				if (!groupMap.has(key)) {
446					groupMap.set(key, {
447						behaviorName: c.behavior_name ?? null,
448						classifiers: [],
449					});
450				}
451				const group = groupMap.get(key)!;
452	
453				const attrValues = c.attribute_values || {};
454				const values = Object.keys(attrValues);
455	
456				// Detect parent-child from attribute_values.parent field
457				let parentSlug: string | null = null;
458				const valuesByParentValue: Record<string, string[]> = {};
459	
460				for (const [val, config] of Object.entries(attrValues)) {
461					if (config.parent) {
462						for (const [pSlug, pValue] of Object.entries(config.parent)) {
463							parentSlug = pSlug;
464							if (!valuesByParentValue[pValue]) {
465								valuesByParentValue[pValue] = [];
466							}
467							valuesByParentValue[pValue].push(val);
468						}
469					}
470				}
471	
472				const existing = group.classifiers.find((gc) => gc.slug === c.slug);
473				if (existing) {
474					const merged = new Set([...existing.values, ...values]);
475					existing.values = [...merged];
