190	function normalizeClassificationValues(data: unknown): {
191		values: string[];
192		isManual: boolean;
193	} {
194		if (data && typeof data === "object") {
195			const valueObj = data as {
196				value?: unknown;
197				values?: unknown;
198				is_manual?: unknown;
199			};
200	
201			if (Array.isArray(valueObj.values)) {
202				return {
203					values: valueObj.values
204						.map((v) => String(v))
205						.filter((v) => v.length > 0),
206					isManual: valueObj.is_manual === true,
207				};
208			}
209	
210			if (valueObj.value !== undefined && valueObj.value !== null) {
211				return {
212					values: [String(valueObj.value)],
213					isManual: valueObj.is_manual === true,
214				};
215			}
216	
217			if (typeof valueObj.values === "string" && valueObj.values.length > 0) {
218				return {
219					values: [valueObj.values],
220					isManual: valueObj.is_manual === true,
221				};
222			}
223		}
224	
225		if (
226			typeof data === "string" ||
227			typeof data === "number" ||
228			typeof data === "boolean" ||
229			typeof data === "bigint"
230		) {
231			return { values: [String(data)], isManual: false };
232		}
233	
234		return { values: [], isManual: false };
235	}
