455	function stringOrUndefined(value: unknown): string | undefined {
456		return typeof value === "string" ? value : undefined;
457	}
458	
459	function buildMergeDetails(metadata: Record<string, unknown>): MergeDetails {
460		const current = asRecord(metadata.current);
461		const proposal = asRecord(metadata.proposal);
462		const winner = asRecord(current?.winner);
463		const loser = asRecord(current?.loser);
464		const duplicates = Array.isArray(current?.duplicates)
465			? current.duplicates.map(asRecord)
466			: [];
467		const snapshotLosers =
468			duplicates.length > 0 ? duplicates : loser ? [loser] : [];
469	
470		const losersFromSnapshot = snapshotLosers.flatMap((snapshot) => {
471			const name = stringOrUndefined(snapshot?.name);
472			const id = snapshot?.id;
473			return name && (typeof id === "string" || typeof id === "number")
474				? [
475						{
476							key: String(id),
477							name,
478							slug: stringOrUndefined(snapshot?.slug),
479							entityType: stringOrUndefined(snapshot?.entity_type),
480							parentSlug: stringOrUndefined(snapshot?.parent_slug),
481							parentEntityType: stringOrUndefined(snapshot?.parent_entity_type),
482						},
483					]
484				: [];
485		});
486		const proposalIds = Array.isArray(proposal?.entity_ids)
487			? proposal.entity_ids
488			: [];
489		const losersFromProposal = Array.isArray(proposal?.names)
490			? proposal.names.flatMap((name, index) => {
491					const id = proposalIds[index];
492					return typeof name === "string" &&
493						(typeof id === "string" || typeof id === "number")
494						? [{ key: String(id), name }]
495						: [];
496				})
497			: [];
498		const fallbackName = stringOrUndefined(proposal?.name);
499		const fallbackId = proposal?.entity_id;
500	
501		const losers =
502			losersFromSnapshot.length > 0
503				? losersFromSnapshot
504				: losersFromProposal.length > 0
505					? losersFromProposal
506					: fallbackName &&
507							(typeof fallbackId === "string" || typeof fallbackId === "number")
508						? [{ key: String(fallbackId), name: fallbackName }]
509						: [];
510	
511		return {
512			winnerName:
513				stringOrUndefined(winner?.name) ??
514				stringOrUndefined(proposal?.winner_name),
515			winnerSlug: stringOrUndefined(winner?.slug),
516			winnerEntityType: stringOrUndefined(winner?.entity_type),
517			winnerParentSlug: stringOrUndefined(winner?.parent_slug),
518			winnerParentEntityType: stringOrUndefined(winner?.parent_entity_type),
519			losers,
520			matchEvidence: evidenceOf(proposal),
521		};
522	}
