524	/**
525	 * The card header stays short on merges — the Kept/Merged-away panel right
526	 * below already names both entities, so spelling them out again here is noise.
527	 * The name-rich "Merge X into Y" form lives server-side on the event title,
528	 * which is what timelines and notifications show without the panel.
529	 */
530	function formatEntityChangeAction(details: EntityChangeDetails): string {
531		const entityLabel = details.entityType
532			? formatLabel(details.entityType).toLowerCase()
533			: "entity";
534		if (details.operation === "merge") {
535			const losers = details.merge?.losers ?? [];
536			return losers.length > 1
537				? `Merge ${losers.length} duplicate ${entityLabel}s`
538				: `Merge duplicate ${entityLabel}`;
539		}
540		return `${formatLabel(details.operation)} ${entityLabel}`;
541	}
