543	function getEntityChangeDetails(
544		content: ContentItem,
545		metadata: Record<string, unknown>,
546	): EntityChangeDetails | null {
547		if (
548			metadata.action_key !== "entity_change" &&
549			metadata.tool !== "entity_change"
550		) {
551			return null;
552		}
553		const operation = metadata.action;
554		if (
555			operation !== "create" &&
556			operation !== "delete" &&
557			operation !== "merge"
558		) {
559			return null;
560		}
561		const contentWithEntity = content as ContentItem & {
562			entity_name?: string | null;
563		};
564		return {
565			operation,
566			merge: operation === "merge" ? buildMergeDetails(metadata) : undefined,
567			proposal: asRecord(metadata.proposal),
568			current: asRecord(metadata.current),
569			reason: typeof metadata.reason === "string" ? metadata.reason : undefined,
570			watcherId:
571				metadata.watcher_id != null ? String(metadata.watcher_id) : undefined,
572			watcherName:
573				typeof metadata.watcher_name === "string"
574					? metadata.watcher_name
575					: undefined,
576			watcherAgentId:
577				typeof metadata.watcher_agent_id === "string"
578					? metadata.watcher_agent_id
579					: undefined,
580			entityType:
581				typeof metadata.entity_type === "string"
582					? metadata.entity_type
583					: undefined,
584			entityName:
585				(typeof metadata.entity_name === "string"
586					? metadata.entity_name
587					: undefined) ??
588				contentWithEntity.entity_name ??
589				undefined,
590			entitySlug:
591				typeof metadata.entity_slug === "string"
592					? metadata.entity_slug
593					: undefined,
594			parentSlug:
595				typeof metadata.parent_slug === "string"
596					? metadata.parent_slug
597					: undefined,
598			parentEntityType:
599				typeof metadata.parent_entity_type === "string"
600					? metadata.parent_entity_type
601					: undefined,
602			attribution:
603				typeof metadata.attribution === "string"
604					? metadata.attribution
605					: undefined,
606			proposerRationale:
607				typeof metadata.proposer_rationale === "string"
608					? metadata.proposer_rationale
609					: undefined,
610			initiator:
611				metadata.initiator && typeof metadata.initiator === "object"
612					? (metadata.initiator as RunInitiator)
613					: undefined,
614		};
