9	/**
10	 * Default loading placeholder for a tab- or page-sized content region.
11	 *
12	 * Renders shimmer rows that mirror the final layout shape rather than a
13	 * spinner + "Loading…" string. Per DESIGN_GUIDELINES §5, skeletons are the
14	 * preferred loading UX for any content panel; bare loader text is reserved
15	 * for tiny inline regions and sub-1s auth handoffs.
16	 *
17	 * Pick a variant that roughly matches what's about to render:
18	 *  - `rows` (default) — for table-style lists. Renders a header bar + N
19	 *    full-width rows inside a bordered surface.
20	 *  - `cards` — for grouped sections (oauth-apps, settings). Each "card" is
21	 *    a bordered block with a title bar + a few rows.
22	 *  - `panel` — for a single content panel with a heading; one title bar +
23	 *    a few paragraph-width bars.
24	 *  - `list-picker` — search field + stacked bordered pick rows (clone dialogs).
25	 *  - `table` — bordered table with header cells + data rows (compact tables).
26	 *
27	 * The `label` is exposed via `aria-label` so screen readers still hear
28	 * "Loading <thing>…" without users seeing it.
29	 */
30	export function TabLoadingState({
31		label,
32		variant = "rows",
33		rows = 5,
34		cards = 2,
35		className,
36	}: {
37		label: string;
38		variant?: "rows" | "cards" | "panel" | "list-picker" | "table";
39		rows?: number;
40		cards?: number;
41		className?: string;
