43		if (variant === "list-picker") {
44			return (
45				<div
46					role="status"
47					aria-label={`Loading ${label}`}
48					className={cn("space-y-3", className)}
49				>
50					<Skeleton className="h-9 w-full rounded-md" />
51					<div className="space-y-2">
52						{Array.from({ length: rows }).map((_, i) => (
53							<div
54								// biome-ignore lint/suspicious/noArrayIndexKey: static skeleton rows
55								key={i}
56								className="space-y-2 rounded-md border p-3"
57							>
58								<Skeleton className="h-4 w-2/5" />
59								<Skeleton className="h-3 w-1/2" />
60							</div>
61						))}
62					</div>
63				</div>
